<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import { Plus,Refresh,Search } from '@element-plus/icons-vue';import type { components } from '@ism/api-client';import { useSessionStore } from '../stores/session';
type Person=components['schemas']['SupplierPerson'];type Asset=components['schemas']['SupplierAsset'];type Supplier=components['schemas']['SupplierSummary'];type Project=components['schemas']['ProjectSummary'];
const session=useSessionStore(),route=useRoute(),router=useRouter();const tab=computed(()=>route.meta.tab as 'persons'|'assets');const loading=ref(false),dialog=ref(false),total=ref(0);const persons=ref<Person[]>([]),assets=ref<Asset[]>([]),suppliers=ref<Supplier[]>([]),projects=ref<Project[]>([]);const query=reactive({keyword:'',status:'',page:0,size:20});
const personForm=reactive({code:'',name:'',supplierId:'',projectId:'',idType:'NATIONAL_ID' as components['schemas']['IdType'],idNumber:'',mobile:'',jobTitle:'',tradeType:'',entryDate:''});
const assetForm=reactive({code:'',name:'',supplierId:'',projectId:'',type:'VEHICLE' as components['schemas']['AssetType'],plateNo:'',serialNo:'',brand:'',model:'',inspectionExpiryDate:'',fileId:''});
const personStatuses={PENDING:'待入场',ACTIVE:'在场',SUSPENDED:'已停用',EXITED:'已离场'},assetStatuses={PENDING:'待验收',AVAILABLE:'可用',IN_USE:'使用中',MAINTENANCE:'维修中',RETIRED:'已退役'},assetTypes={VEHICLE:'车辆',EQUIPMENT:'设备',TOOL:'工器具'};
const availableProjects=computed(()=>projects.value.filter(x=>x.supplierId===(tab.value==='persons'?personForm.supplierId:assetForm.supplierId)));
async function load(){loading.value=true;try{if(tab.value==='persons'){const {data}=await session.client.GET('/resources/persons',{params:{query:{keyword:query.keyword||undefined,status:(query.status||undefined) as components['schemas']['PersonStatus']|undefined,page:query.page,size:query.size}}});persons.value=data?.data?.items??[];total.value=data?.data?.total??0;}else{const {data}=await session.client.GET('/resources/assets',{params:{query:{keyword:query.keyword||undefined,status:(query.status||undefined) as components['schemas']['AssetStatus']|undefined,page:query.page,size:query.size}}});assets.value=data?.data?.items??[];total.value=data?.data?.total??0;}}finally{loading.value=false;}}
async function openCreate(){const [s,p]=await Promise.all([session.client.GET('/suppliers',{params:{query:{status:'ACTIVE',page:0,size:100}}}),session.client.GET('/projects',{params:{query:{page:0,size:100}}})]);suppliers.value=s.data?.data?.items??[];projects.value=p.data?.data?.items??[];Object.assign(personForm,{code:'',name:'',supplierId:'',projectId:'',idType:'NATIONAL_ID',idNumber:'',mobile:'',jobTitle:'',tradeType:'',entryDate:''});Object.assign(assetForm,{code:'',name:'',supplierId:'',projectId:'',type:'VEHICLE',plateNo:'',serialNo:'',brand:'',model:'',inspectionExpiryDate:'',fileId:''});dialog.value=true;}
async function save(){if(tab.value==='persons'){const f=personForm;if(!f.code||!f.name||!f.supplierId||!f.idNumber){ElMessage.warning('请完整填写人员必填项');return;}const {error}=await session.client.POST('/resources/persons',{body:{...f,projectId:f.projectId||undefined,mobile:f.mobile||undefined,jobTitle:f.jobTitle||undefined,tradeType:f.tradeType||undefined,entryDate:f.entryDate||undefined,version:0}});if(error){ElMessage.error(error.error.message);return;}}else{const f=assetForm;if(!f.code||!f.name||!f.supplierId||(f.type==='VEHICLE'&&!f.plateNo)){ElMessage.warning('请完整填写车辆设备必填项');return;}const {error}=await session.client.POST('/resources/assets',{body:{...f,projectId:f.projectId||undefined,plateNo:f.plateNo||undefined,serialNo:f.serialNo||undefined,brand:f.brand||undefined,model:f.model||undefined,inspectionExpiryDate:f.inspectionExpiryDate||undefined,fileId:f.fileId||undefined,version:0}});if(error){ElMessage.error(error.error.message);return;}}dialog.value=false;ElMessage.success('登记成功');await load();}
async function personStatus(row:Person,status:components['schemas']['PersonStatus']){let reason:string|undefined;if(status==='SUSPENDED'||status==='EXITED')reason=(await ElMessageBox.prompt('请输入变更原因','人员状态',{inputPattern:/.+/})).value;else await ElMessageBox.confirm(`确认变更为“${personStatuses[status]}”？`,'状态确认');const {error}=await session.client.POST('/resources/persons/{id}/status',{params:{path:{id:row.id}},body:{status,reason,version:row.version}});if(error)ElMessage.error(error.error.message);else await load();}
async function assetStatus(row:Asset,status:components['schemas']['AssetStatus']){let reason:string|undefined;if(status==='MAINTENANCE'||status==='RETIRED')reason=(await ElMessageBox.prompt('请输入变更原因','资产状态',{inputPattern:/.+/})).value;else await ElMessageBox.confirm(`确认变更为“${assetStatuses[status]}”？`,'状态确认');const {error}=await session.client.POST('/resources/assets/{id}/status',{params:{path:{id:row.id}},body:{status,reason,version:row.version}});if(error)ElMessage.error(error.error.message);else await load();}
function switchTab(name:string){void router.push(name==='persons'?'/resources/persons':'/resources/assets');}watch(()=>route.path,()=>{query.status='';query.page=0;void load();});onMounted(load);
</script>
<template><div class="page"><div class="page-heading"><div><h1>{{tab==='persons'?'供应商人员':'车辆设备'}}</h1><p>{{tab==='persons'?'统一登记承包商入场人员、工种和项目归属':'管理车辆、设备和工器具的验收与使用状态'}}</p></div><el-button type="primary" :icon="Plus" @click="openCreate">{{tab==='persons'?'登记人员':'登记资产'}}</el-button></div><el-tabs :model-value="tab" @tab-change="switchTab"><el-tab-pane label="供应商人员" name="persons"/><el-tab-pane label="车辆设备" name="assets"/></el-tabs>
<el-card shadow="never" class="filter-card"><el-form inline><el-form-item label="关键词"><el-input v-model="query.keyword" clearable :prefix-icon="Search" placeholder="编码、名称、供应商"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable placeholder="全部状态" style="width:150px"><el-option v-for="(name,key) in (tab==='persons'?personStatuses:assetStatuses)" :key="key" :label="name" :value="key"/></el-select></el-form-item><el-button type="primary" @click="query.page=0;load()">查询</el-button><el-button :icon="Refresh" @click="query.keyword='';query.status='';load()">重置</el-button></el-form></el-card>
<el-card v-if="tab==='persons'" shadow="never" class="table-card"><el-table v-loading="loading" :data="persons"><el-table-column prop="code" label="人员编码" width="140"/><el-table-column label="人员/供应商" min-width="230"><template #default="{row}"><strong>{{row.name}}</strong><div class="subtext">{{row.supplierName}}</div></template></el-table-column><el-table-column prop="idNumberMasked" label="证件号码" width="180"/><el-table-column prop="tradeType" label="工种" width="130"/><el-table-column prop="projectCode" label="所属项目" width="140"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag>{{personStatuses[row.status as keyof typeof personStatuses]}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button v-if="row.status==='PENDING'||row.status==='SUSPENDED'" link type="primary" @click="personStatus(row,'ACTIVE')">启用</el-button><el-button v-if="row.status==='ACTIVE'" link type="warning" @click="personStatus(row,'SUSPENDED')">停用</el-button><el-button v-if="row.status!=='EXITED'" link type="danger" @click="personStatus(row,'EXITED')">离场</el-button></template></el-table-column></el-table></el-card>
<el-card v-else shadow="never" class="table-card"><el-table v-loading="loading" :data="assets"><el-table-column prop="code" label="资产编码" width="140"/><el-table-column label="资产/供应商" min-width="230"><template #default="{row}"><strong>{{row.name}}</strong><div class="subtext">{{row.supplierName}}</div></template></el-table-column><el-table-column label="类型" width="100"><template #default="{row}">{{assetTypes[row.type as keyof typeof assetTypes]}}</template></el-table-column><el-table-column prop="plateNo" label="车牌号" width="130"/><el-table-column prop="projectCode" label="所属项目" width="140"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag>{{assetStatuses[row.status as keyof typeof assetStatuses]}}</el-tag></template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button v-if="row.status==='PENDING'||row.status==='MAINTENANCE'||row.status==='IN_USE'" link type="primary" @click="assetStatus(row,'AVAILABLE')">可用</el-button><el-button v-if="row.status==='AVAILABLE'" link type="success" @click="assetStatus(row,'IN_USE')">投入使用</el-button><el-button v-if="row.status==='AVAILABLE'||row.status==='IN_USE'" link type="warning" @click="assetStatus(row,'MAINTENANCE')">维修</el-button><el-button v-if="row.status!=='RETIRED'&&row.status!=='IN_USE'" link type="danger" @click="assetStatus(row,'RETIRED')">退役</el-button></template></el-table-column></el-table></el-card>
<el-dialog v-model="dialog" :title="tab==='persons'?'登记供应商人员':'登记车辆设备'" width="720px"><el-form v-if="tab==='persons'" label-position="top"><el-row :gutter="18"><el-col :span="12"><el-form-item label="人员编码 *"><el-input v-model="personForm.code"/></el-form-item></el-col><el-col :span="12"><el-form-item label="姓名 *"><el-input v-model="personForm.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="供应商 *"><el-select v-model="personForm.supplierId" filterable style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="所属项目"><el-select v-model="personForm.projectId" clearable style="width:100%"><el-option v-for="p in availableProjects" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="证件类型"><el-select v-model="personForm.idType"><el-option label="居民身份证" value="NATIONAL_ID"/><el-option label="护照" value="PASSPORT"/><el-option label="其他" value="OTHER"/></el-select></el-form-item></el-col><el-col :span="16"><el-form-item label="证件号码 *"><el-input v-model="personForm.idNumber"/></el-form-item></el-col><el-col :span="8"><el-form-item label="手机"><el-input v-model="personForm.mobile"/></el-form-item></el-col><el-col :span="8"><el-form-item label="岗位"><el-input v-model="personForm.jobTitle"/></el-form-item></el-col><el-col :span="8"><el-form-item label="工种"><el-input v-model="personForm.tradeType"/></el-form-item></el-col></el-row></el-form><el-form v-else label-position="top"><el-row :gutter="18"><el-col :span="12"><el-form-item label="资产编码 *"><el-input v-model="assetForm.code"/></el-form-item></el-col><el-col :span="12"><el-form-item label="资产名称 *"><el-input v-model="assetForm.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="供应商 *"><el-select v-model="assetForm.supplierId" filterable style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="所属项目"><el-select v-model="assetForm.projectId" clearable style="width:100%"><el-option v-for="p in availableProjects" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="资产类型"><el-select v-model="assetForm.type"><el-option label="车辆" value="VEHICLE"/><el-option label="设备" value="EQUIPMENT"/><el-option label="工器具" value="TOOL"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="车牌号"><el-input v-model="assetForm.plateNo"/></el-form-item></el-col><el-col :span="8"><el-form-item label="出厂编号"><el-input v-model="assetForm.serialNo"/></el-form-item></el-col><el-col :span="8"><el-form-item label="品牌"><el-input v-model="assetForm.brand"/></el-form-item></el-col><el-col :span="8"><el-form-item label="型号"><el-input v-model="assetForm.model"/></el-form-item></el-col><el-col :span="8"><el-form-item label="检验到期日"><el-date-picker v-model="assetForm.inspectionExpiryDate" value-format="YYYY-MM-DD"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">确认登记</el-button></template></el-dialog><div class="pagination"><span>共 {{total}} 条</span></div></div></template>
